Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_set_valid_index(void) {
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);

    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    if (fill_result != 0) {
        helper_cleanup_vector(vec);
        TEST_FAIL_MESSAGE("Failed to fill vector");
    }
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    int original_len = vec->len;
    TEST_ASSERT_EQUAL_INT(3, original_len);

    int index = 1;
    int new_val = 99;

    set(vec, index, new_val);

    int retrieved_val = vec->contents[index];
    TEST_ASSERT_EQUAL_INT(new_val, retrieved_val);

    int unchanged_val_0 = vec->contents[0];
    TEST_ASSERT_EQUAL_INT(10, unchanged_val_0);

    int unchanged_val_2 = vec->contents[2];
    TEST_ASSERT_EQUAL_INT(30, unchanged_val_2);

    int current_len = vec->len;
    TEST_ASSERT_EQUAL_INT(original_len, current_len);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_set_valid_index);
    return UNITY_END();
}

